-- Additional pending migration. Local/staging verification required before production approval.
-- Preserve every historical reference. New Yoco references are generated by the
-- database from its unique attempt UUID and cannot be supplied or changed by a client.
begin;
set local lock_timeout='5s';
set local statement_timeout='90s';
create or replace function kagie_private.pin_yoco_reference() returns trigger
language plpgsql set search_path='' as $$
begin
 if tg_op='INSERT' and new.provider='yoco' then
  new.reference:='KAG-YOCO-'||upper(replace(new.id::text,'-',''));
 elsif tg_op='UPDATE' and old.provider='yoco' and new.reference is distinct from old.reference then
  raise exception 'Payment reference is immutable';
 end if;
 return new;
end;$$;
drop trigger if exists yoco_pin_reference on public.payments;
create trigger yoco_pin_reference before insert or update on public.payments
for each row execute function kagie_private.pin_yoco_reference();
revoke all on function kagie_private.pin_yoco_reference() from public,anon,authenticated;
create or replace function public.reserve_yoco_checkout(p_application_id uuid,p_user_id uuid,p_provider text,p_fingerprint text,p_order_key text,p_payment jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
declare l public.payment_checkout_leases;pay public.payments;result jsonb;
begin
 if current_setting('role',true)<>'service_role' then raise exception 'Trusted checkout service required' using errcode='42501'; end if;
 if p_provider is distinct from 'yoco' or coalesce(p_payment#>>'{checkout_snapshot,gatewayMode}','') not in ('test','live') then raise exception 'Invalid Yoco reservation'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_user_id::text||p_order_key,0));
 perform 1 from public.applications where id=p_application_id and user_id=p_user_id for update;
 if not found then raise exception 'Application unavailable'; end if;
 select * into l from public.payment_checkout_leases where application_id=p_application_id for update;
 if found and l.provider='yoco' and l.response is null and l.created_at<now()-interval '15 minutes' then
  raise exception 'This interrupted checkout needs provider reconciliation before retrying. Contact Kagie with your reference.';
 end if;
 if found and l.provider='yoco' and l.order_key<>p_order_key then
  select * into pay from public.payments where id=l.payment_id;
  if pay.status='Verified' and pay.checkout_snapshot->'containsApplicationPack'='false'::jsonb then
   delete from public.payment_checkout_leases where application_id=p_application_id;
   insert into public.payment_reconciliation(payment_id,application_id,provider,event_key,kind,resolved_at,resolution)
    values(pay.id,pay.application_id,'yoco','lease-completed:'||pay.id,'service_checkout_completed',now(),'Verified service order completed; new order may reserve a checkout') on conflict(event_key) do nothing;
  end if;
 end if;
 result:=public.reserve_payment_checkout(p_application_id,p_user_id,p_provider,p_fingerprint,p_order_key,p_payment);
 select * into pay from public.payments where id=(result->>'payment_id')::uuid;
 return result || jsonb_build_object('reference',pay.reference);
end;$$;
revoke all on function public.reserve_yoco_checkout(uuid,uuid,text,text,text,jsonb) from public,anon,authenticated;
grant execute on function public.reserve_yoco_checkout(uuid,uuid,text,text,text,jsonb) to service_role;


-- Fill only the owner field added by the upgrade; never overwrite a recorded owner.
update public.payments p set user_id=a.user_id from public.applications a where p.application_id=a.id and p.user_id is null;

-- Freeze the catalog display data at submission time for bank-transfer receipts.
create or replace function public.record_manual_payment(p_application_id uuid,p_owner_id uuid,p_pack_id uuid,p_payer_name text,p_phone text,p_reference text,p_method text,p_note text)
returns jsonb language plpgsql security definer set search_path='' as $$
declare a public.applications;p public.payments;pack public.application_packs;
begin
 if current_setting('role',true)<>'service_role' and (not kagie_private.account_active() or auth.uid() is distinct from p_owner_id) then raise exception 'Application unavailable' using errcode='42501'; end if;
 if p_method not in ('EFT','Cash Deposit','Card Transfer','Mobile Payment') or length(trim(p_reference)) not between 2 and 200 or length(trim(p_payer_name)) not between 2 and 200 or length(p_phone) not between 6 and 80 or (length(coalesce(p_note,''))>2000 or coalesce(p_note,'') like '__KAGIE_PAYMENT_META__%') then raise exception 'Invalid manual payment details' using errcode='22023'; end if;
 select * into a from public.applications where id=p_application_id for update;
 if a.id is null or a.user_id is distinct from p_owner_id then raise exception 'Application unavailable' using errcode='42501'; end if;
 select * into p from public.payments where application_id=a.id and provider='manual' and reference=trim(p_reference) and method=p_method order by created_at desc limit 1;
 if found then return jsonb_build_object('payment',to_jsonb(p),'duplicate',true); end if;
 if a.payment_status in ('Verified','Paid','Refunded') or exists(select 1 from public.payment_checkout_leases where application_id=a.id) or exists(select 1 from public.payments where application_id=a.id and status in ('Payment Pending','Pending Verification','Pending','Paid','Verified')) then raise exception 'A payment is already active or confirmed. Resume it or request reconciliation.' using errcode='P0001'; end if;
 select * into pack from public.application_packs where id=p_pack_id and is_active;
 if pack.id is null or pack.price<=0 then raise exception 'Package price is unavailable' using errcode='22023'; end if;
 insert into public.payments(application_id,user_id,payer_name,phone,reference,method,note,amount,status,provider,currency,checkout_snapshot)
 values(a.id,p_owner_id,trim(p_payer_name),p_phone,trim(p_reference),p_method,coalesce(p_note,''),pack.price,'Pending Verification','manual','ZAR',jsonb_build_object('packId',pack.id,'services','[]'::jsonb,'products',jsonb_build_array(jsonb_build_object('catalogId',pack.id,'type','application_pack','name',pack.name,'quantity',1,'amountCents',round(pack.price*100))))) returning * into p;
 update public.applications set package_id=pack.id,application_type=pack.application_type,payer_name=p.payer_name,payer_phone=p.phone,payment_reference=p.reference,payment_method=p.method,payment_note=p.note,payment_amount=pack.price,payment_status='Pending Verification',status='Awaiting Payment',updated_at=now() where id=a.id;
 insert into public.notifications(user_id,title,message,notification_type) values(p_owner_id,'Payment submitted','Your manual payment is awaiting staff verification.','info');
 -- Clear only this application's purchased package within the submission transaction.
 -- A retry returns above and cannot remove a later cart. Other service orders survive.
 perform 1 from public.carts where user_id=p_owner_id for update;
 delete from public.cart_items ci using public.carts c where ci.cart_id=c.id and c.user_id=p_owner_id
  and ci.metadata->>'applicationId'=a.id::text
  and (ci.item_type='application_pack' and ci.ref_id=pack.id or ci.item_type='institution');
 update public.carts c set total_amount=coalesce((select sum(ci.price*ci.quantity) from public.cart_items ci where ci.cart_id=c.id),0),updated_at=now() where c.user_id=p_owner_id;
 return jsonb_build_object('payment',to_jsonb(p),'duplicate',false);
end; $$;
revoke all on function public.record_manual_payment(uuid,uuid,uuid,text,text,text,text,text) from public,anon;
grant execute on function public.record_manual_payment(uuid,uuid,uuid,text,text,text,text,text) to authenticated,service_role;


commit;
